<header class="page-head"><p class="kicker">Stock control</p><h1>Inventory</h1><p class="lead">Count what's on the shelf. Anything at or below par is flagged.</p></header>
<div class="panel-headline"><h2>Current stock <span class="counter">4</span></h2><span class="muted">Staff record counts. Managers edit items.</span></div>
<section class="panel inventory-panel">
<form method="get" class="filter-row inventory-sort"><label class="field"><span>Sort stock by</span><select name="sort"><option value="category" selected>Category</option><option value="item">Item name</option><option value="quantity">Quantity</option><option value="variance">Variance from par</option></select></label><label class="field"><span>Order</span><select name="direction"><option value="asc" selected>Ascending</option><option value="desc">Descending</option></select></label><button class="btn btn-light" type="submit">Sort</button></form>
<div class="table-wrap" role="region" aria-label="Inventory table" tabindex="0"><table class="data-table"><caption class="sr-only">Inventory, thresholds and quantity updates</caption><thead><tr><th scope="col">Item</th><th scope="col">Quantity / par</th><th scope="col">Variance from par</th><th scope="col">Unit cost</th><th scope="col">Record physical count</th><th scope="col">Manage</th></tr></thead><tbody>
<tr class="low-stock"><td data-label="Item"><strong>Oat milk</strong><small>Dairy</small><span class="stock-warning">Low stock</span></td><td data-label="Quantity / par"><strong>3 L</strong><small>Par 6 L</small></td><td data-label="Variance from par"><strong>-3 L</strong><small>Counted minus par</small></td><td data-label="Unit cost">₱120.00</td><td data-label="Count"><form class="inline-form" method="post"><input type="number" name="quantity" step="0.01" min="0" value="3" required><button type="submit" class="btn btn-small">Save</button></form></td><td data-label="Manage"><div class="actions"><a class="text-link" href="?edit=1#item-form">Edit</a><form method="post" data-confirm="Delete this item? This can't be undone."><button class="danger-link" type="submit">Delete</button></form></div></td></tr>
<tr class="low-stock"><td data-label="Item"><strong>Espresso beans</strong><small>Coffee</small><span class="stock-warning">Low stock</span></td><td data-label="Quantity / par"><strong>2 kg</strong><small>Par 5 kg</small></td><td data-label="Variance from par"><strong>-3 kg</strong><small>Counted minus par</small></td><td data-label="Unit cost">₱950.00</td><td data-label="Count"><form class="inline-form" method="post"><input type="number" name="quantity" step="0.01" min="0" value="2" required><button type="submit" class="btn btn-small">Save</button></form></td><td data-label="Manage"><div class="actions"><a class="text-link" href="?edit=2#item-form">Edit</a><form method="post" data-confirm="Delete this item? This can't be undone."><button class="danger-link" type="submit">Delete</button></form></div></td></tr>
<tr class="low-stock"><td data-label="Item"><strong>Cups 12 oz</strong><small>Packaging</small><span class="stock-warning">Low stock</span></td><td data-label="Quantity / par"><strong>40 pcs</strong><small>Par 100 pcs</small></td><td data-label="Variance from par"><strong>-60 pcs</strong><small>Counted minus par</small></td><td data-label="Unit cost">₱45.00</td><td data-label="Count"><form class="inline-form" method="post"><input type="number" name="quantity" step="0.01" min="0" value="40" required><button type="submit" class="btn btn-small">Save</button></form></td><td data-label="Manage"><div class="actions"><a class="text-link" href="?edit=3#item-form">Edit</a><form method="post" data-confirm="Delete this item? This can't be undone."><button class="danger-link" type="submit">Delete</button></form></div></td></tr>
<tr><td data-label="Item"><strong>Whole milk</strong><small>Dairy</small></td><td data-label="Quantity / par"><strong>12 L</strong><small>Par 8 L</small></td><td data-label="Variance from par"><strong>+4 L</strong><small>Counted minus par</small></td><td data-label="Unit cost">₱95.00</td><td data-label="Count"><form class="inline-form" method="post"><input type="number" name="quantity" step="0.01" min="0" value="12" required><button type="submit" class="btn btn-small">Save</button></form></td><td data-label="Manage"><div class="actions"><a class="text-link" href="?edit=4#item-form">Edit</a><form method="post" data-confirm="Delete this item? This can't be undone."><button class="danger-link" type="submit">Delete</button></form></div></td></tr>
</tbody></table></div>
</section>
<section class="panel edit-panel" id="item-form"><div class="panel-heading"><h2>Add item</h2></div>
<form method="post" class="grid-form">
<label class="field"><span>Item name</span><input name="item_name" required maxlength="100" value=""></label>
<label class="field"><span>Category</span><input name="category" required maxlength="50" placeholder="Coffee, dairy, syrup" value=""></label>
<label class="field"><span>Quantity</span><input name="quantity" type="number" min="0" max="99999999" step="0.01" required value="0"></label>
<label class="field"><span>Unit</span><input name="unit" required maxlength="20" value="pcs"></label>
<label class="field"><span>Par level</span><input name="par_level" type="number" min="0" step="0.01" max="99999999" required value="0"></label>
<label class="field"><span>Unit cost (₱)</span><input name="unit_cost" type="number" min="0" step="0.01" max="99999999" required value="0"></label>
<div class="form-submit"><button class="btn btn-primary" type="submit">Add item</button></div></form></section>
